arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H "Content-Type: application/json" -d '{"token":"***","exclude_archived":true,"limit":1000,"types":"public_channel,private_channel"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
print('ok:',d.get('ok'),'err:',d.get('error'))
for key in ('channels','groups'):
    for c in d.get(key,[]):
        name=c.get('name','')
        if 'incident' in name.lower():
            print(key,'|',name, c.get('id'), '| is_archived:',c.get('is_archived'), '| topic:', repr(c.get('topic',{}).get('text','')))
"

